// Turns the analysis model into the generated files. Output is deterministic (sorted input,
// Prettier-formatted), so `generate --check` can compare it byte-for-byte with what's committed.

import { resolve } from 'node:path';
import prettier from 'prettier';
import { config } from './config.mjs';

const HEADER = (what) =>
  `// GENERATED by scripts/puck/generate.mjs - do not edit by hand.\n` +
  `// Source: stories tagged '${config.tag}' and their Angular components. ${what}\n` +
  `// Regenerate: pnpm puck:generate\n`;

/** @returns {Promise<Record<string, string>>} repo-relative path → file content */
export async function renderFiles(root, blocks) {
  const files = {
    [config.out.elements]: elementsFile(blocks),
    [config.out.typings]: typingsFile(blocks),
    [config.out.blocks]: blocksFile(blocks),
    [config.out.manifest]: JSON.stringify(manifest(blocks), null, 2) + '\n',
  };
  for (const [path, content] of Object.entries(files)) {
    if (path.endsWith('.json')) continue;
    const options = (await prettier.resolveConfig(resolve(root, path))) ?? {};
    files[path] = await prettier.format(content, { ...options, filepath: resolve(root, path) });
  }
  return files;
}

/** ③ tag → component map for the Angular Elements build. */
function elementsFile(blocks) {
  const names = [...new Set(blocks.map((b) => b.exportName))].sort();
  return `${HEADER('Step ③: custom element registry.')}
import type { Type } from '@angular/core';
import { ${names.join(', ')} } from '${config.libraryImport}';

export const elements: Record<string, Type<unknown>> = {
${blocks.map((b) => `  '${b.tag}': ${b.exportName},`).join('\n')}
};
`;
}

/** ④ JSX typings for the custom elements. */
function typingsFile(blocks) {
  return `${HEADER('Step ④: JSX typings for the custom elements.')}
import type { DetailedHTMLProps, HTMLAttributes, RefObject } from 'react';

type El<P> = DetailedHTMLProps<HTMLAttributes<HTMLElement>, HTMLElement> &
  P & { ref?: RefObject<HTMLElement | null> };

declare module 'react' {
  namespace JSX {
    interface IntrinsicElements {
${blocks.map((b) => `      '${b.tag}': El<{ ${b.props.map((p) => `${p.name}?: ${tsTypeOf(p)};`).join(' ')} }>;`).join('\n')}
    }
  }
}
`;
}

/** ⑤ Puck block configs, categories and the props type. */
function blocksFile(blocks) {
  const categories = new Map();
  for (const b of blocks) {
    if (!categories.has(b.category)) categories.set(b.category, []);
    categories.get(b.category).push(b);
  }
  const sortedCategories = [...categories.entries()].sort(([a], [b]) => a.localeCompare(b));

  const propsType = (b) => {
    const fields = b.props.map((p) => `${p.name}: ${tsTypeOf(p)};`);
    if (b.slot) fields.push(`${b.slot}: Slot;`);
    return `{ ${fields.join(' ')} }`;
  };

  const block = (b) => {
    const fields = b.props.map((p) => `${p.name}: ${JSON.stringify(p.field)},`);
    const defaults = b.props.map((p) => `${p.name}: ${JSON.stringify(p.default)},`);
    if (b.slot) {
      fields.push(`${b.slot}: { type: 'slot' },`);
      defaults.push(`${b.slot}: [],`);
    }
    // Puck passes id/editMode/puck to every render; spread onto a custom element React would write
    // them as DOM attributes, so they are pulled out first.
    const render = b.slot
      ? `({ puck: _puck, id: _id, editMode: _editMode, ${b.slot}: Slot, ...props }) => (
          <${b.tag} {...props}><Slot /></${b.tag}>
        )`
      : `({ puck: _puck, id: _id, editMode: _editMode, ...props }) => <${b.tag} {...props} />`;
    return `  // ${b.component} (${b.componentFile}), story: ${b.storyFile}
  ${b.name}: {
    label: ${JSON.stringify(b.label)},
    fields: { ${fields.join(' ')} },
    defaultProps: { ${defaults.join(' ')} },
    render: ${render},
  },`;
  };

  return `${HEADER('Step ⑤: Puck blocks.')}
import type { Config, Slot } from '@puckeditor/core';

export type GeneratedComponents = {
${blocks.map((b) => `  ${b.name}: ${propsType(b)};`).join('\n')}
};

export type GeneratedBlocks = Config<GeneratedComponents>['components'];

export const generatedCategories = {
${sortedCategories
  .map(([title, list]) => `  ${JSON.stringify(slug(title))}: { title: ${JSON.stringify(title)}, components: ${JSON.stringify(list.map((b) => b.name).sort())} as (keyof GeneratedComponents)[] },`)
  .join('\n')}
};

export const generatedBlocks: GeneratedBlocks = {
${blocks.map(block).join('\n')}
};
`;
}

/**
 * Schema snapshot (block types, props, types, defaults). verify.mjs compares it with the committed
 * version to detect changes that would break pages that are already saved.
 */
export function manifest(blocks) {
  return {
    version: 1,
    blocks: Object.fromEntries(
      blocks.map((b) => [
        b.name,
        {
          tag: b.tag,
          label: b.label,
          component: b.exportName,
          selector: b.selector,
          category: b.category,
          slot: b.slot,
          outputs: b.outputs,
          props: Object.fromEntries(
            b.props.map((p) => [p.name, { kind: p.kind, ...(p.options ? { options: p.options } : {}), default: p.default }]),
          ),
          excluded: b.excluded,
        },
      ]),
    ),
  };
}

function tsTypeOf(p) {
  if (p.kind === 'enum') return p.options.map((o) => JSON.stringify(o)).join(' | ');
  return p.kind;
}

const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
